# Lumi 25.1 tests: laundry/cleaning (Open Products Facts + EPA Safer Choice) in Home & Body, recalls (CPSC + openFDA) page and warnings.
# usage: VER=25.1 python3 t251.py <base> [local]
import sys, os, re, json, time, random
exec(open('/workspace/m24/t/t24.py').read().split('with sync_playwright() as p:')[0])
RES = R
def ok(name, cond, info=''):
    RES.append((name, bool(cond))); print(('PASS ' if cond else 'FAIL ') + name + ('' if cond else '  :: ' + str(info)[:700]), flush=True)
VER = os.environ.get('VER', '25.1'); OUT = '/workspace/m25/shots/'
