I = json.load(open(REPO + '/data/hb25/index.json')); IC = json.load(open(REPO + '/data/hb25/index-c.json'))
CATS = [c[0] for c in I['cats']]
RJ = json.load(open(REPO + '/data/recalls25/r.json')); UJ = json.load(open(REPO + '/data/recalls25/u.json'))
def shard(code): return json.load(open(REPO + '/data/hb25/d/%s.json' % code[-2:]))[code]
CD = IC['docs']
with sync_playwright() as p:
    b = p.chromium.launch(); t0 = time.time()
    c = ctx(b, w=1440, h=900); errs = []; pg = page(c, errs)
    pg.goto(base + '#/'); pg.wait_for_function("()=>typeof VERSION!=='undefined'", timeout=30000); pg.wait_for_timeout(800)
    ok('version ' + VER, pg.evaluate('VERSION') == VER)
