    scr = pg.evaluate("[...document.scripts].map(s=>s.getAttribute('src')).filter(Boolean)")
    ok('index loads v251 right after v25', scr[-2:] == ['js/v25.js', 'js/v251.js'], scr[-4:])
    ok("What's new lists 25.1 then 25.0", pg.evaluate("V7_NEWS[0][1]") == 'Laundry, cleaners and recalls (25.1)' and pg.evaluate("V7_NEWS[1][1]") == 'Home & Body (25.0)')
    go(pg, '#/browse', '.hbbr25', 1200)
    r = pg.evaluate("()=>({feat:[...document.querySelectorAll('.fg181 .st181 .m181')].map(a=>a.getAttribute('href')), hb:[...document.querySelectorAll('.hbbr25 a')].map(a=>a.getAttribute('href'))})")
    ok('[browse] Costco + Whole Foods still pinned; Home & Body links to laundry and recalls', set(r['feat']) == {'#/store/wholefoods', '#/store/costco'} and '#/hb/laundry' in r['hb'] and '#/recalls' in r['hb'], r)
    go(pg, '#/hb', '#hbl25 .row', 1800)
    n = int(re.sub(r'\D', '', pg.evaluate("document.getElementById('hbn25').innerText")))
    ok('[hub] All = personal care + laundry/cleaning', n == len(I['docs']) + len(CD), (n, len(I['docs']), len(CD)))
    chips = pg.evaluate("[...document.querySelectorAll('.hbc25 .chip')].map(a=>a.dataset.c)")
    ok('[hub] category chips incl. laundry, dish, surface, air, otherc', len(chips) == 15 and all(x in chips for x in ('laundry', 'dish', 'surface', 'air', 'otherc')), chips)
    ok('[hub] Safer Choice filter chip present', pg.evaluate("!!document.querySelector('.fb25[data-f=sc]')"))
    go(pg, '#/hb/laundry', '#hbl25 .row', 800)
    nl = int(re.sub(r'\D', '', pg.evaluate("document.getElementById('hbn25').innerText")))
    ok('[hub] laundry category count = index', nl == sum(1 for d in CD if CATS[d[4]] == 'laundry') and nl > 200, nl)
    pg.click('.fb25[data-f=sc]'); pg.wait_for_timeout(300)
    tg = pg.evaluate("[...document.querySelectorAll('#hbl25 .row')].map(r=>r.innerText.includes('Safer Choice'))")
    ok('[hub] Safer Choice filter shows only Safer Choice products', len(tg) > 10 and all(tg))
    pg.click('.fb25[data-f=sc]')
