    ok('data: cleaning samples exist', flagged and clean and sc_opf and sc_only, (len(flagged), len(clean), len(sc_opf), len(sc_only)))
    f1 = random.Random(1).choice(flagged); go(pg, '#/cos/' + f1[0], '.hbpg25', 1500); t = txt(pg); rec = shard(f1[0])
