    s1 = random.Random(3).choice(sc_opf); go(pg, '#/cos/' + s1[0], '.hbpg25', 1500); t = txt(pg)
    ok('[safer choice + ingredients] EPA Safer Choice card, positive-label wording, source link; score unchanged by badge', 'EPA Safer Choice' in t and 'not a guarantee' in t and "doesn't use it to hide flags" in t and pg.evaluate("!!document.querySelector('.sc251 a[href*=\"epa.gov/saferchoice\"]')") and pg.evaluate("document.querySelector('.hbs25 .hbp25').innerText") == (str(s1[3]) if s1[3] >= 0 else '?'), t[:400])
    s2 = random.Random(4).choice(sc_only); go(pg, '#/cos/' + s2[0], '.hbpg25', 1500); t = txt(pg)
    ok('[safer choice only] listed product: "Certified by EPA Safer Choice", no number score, no flags invented', 'Certified by EPA Safer Choice' in t and pg.evaluate("document.querySelector('.hbs25 .hbp25').innerText") == '?' and 'Why this score' not in t, t[:400])
