    ok('[recalls] shows the data date and links to cpsc.gov and fda.gov', RJ['asof'] in txt(pg) and pg.evaluate("!!document.querySelector('.rcp251 a[href*=\"cpsc.gov\"]') && !!document.querySelector('.rcp251 a[href*=\"fda.gov\"]')"))
    go(pg, '#/recalls/c', '#rl251 .rc251', 1000)
    nc = int(re.sub(r'\D', '', pg.evaluate("document.getElementById('rn251').innerText")))
    ok('[recalls] Consumer products route filters to CPSC', nc == RJ['counts']['c'] and pg.evaluate("[...document.querySelectorAll('#rl251 .rc251')].every(l=>l.classList.contains('s-c'))"), (nc, RJ['counts']))
    ok('[recalls] every row links to an official https notice', pg.evaluate("[...document.querySelectorAll('#rl251 .rc251')].every(l=>{const a=l.querySelector('a');return a&&/^https:\\/\\/((www\\.)?cpsc\\.gov|www\\.accessdata\\.fda\\.gov)\\//.test(a.href)})"))
    go(pg, '#/recalls/f', '#rl251 .rc251', 1200); pg.click('#c1251'); pg.wait_for_timeout(400)
    n1 = int(re.sub(r'\D', '', pg.evaluate("document.getElementById('rn251').innerText")))
    ok('[recalls] food + Class I only', n1 == sum(1 for a in RJ['items'] if a[1] == 'f' and a[7] == 1) and pg.evaluate("[...document.querySelectorAll('#rl251 .cl251')].every(e=>e.classList.contains('c1'))"), n1)
    pg.fill('#rq251', 'undeclared'); pg.wait_for_timeout(400); nq = pg.evaluate("document.querySelectorAll('#rl251 .rc251').length")
    ok('[recalls] search narrows results', nq > 0 and pg.evaluate("[...document.querySelectorAll('#rl251 .rc251')].every(l=>/undeclared/i.test(l.innerText))"), nq)
    go(pg, '#/recalls/c', '#rl251 .rc251', 1200)
    c.route(re.compile(r'https://www\.saferproducts\.gov/RestWebServices/Recall.*'), lambda rt: rt.fulfill(status=200, content_type='application/json', headers={'access-control-allow-origin': '*'}, body=json.dumps([{'RecallID': 99999999, 'RecallDate': '2099-01-01T00:00:00', 'Title': 'TEST FIXTURE recall', 'URL': 'https://www.cpsc.gov/Recalls', 'Products': [{'Name': 'Test item'}], 'Hazards': [{'Name': 'Test hazard'}], 'Manufacturers': []}])))
    pg.click('#lv251'); pg.wait_for_function("()=>document.getElementById('lv251').innerText.includes('newer CPSC')", timeout=15000)
    ok('[recalls] "Check CPSC for newer recalls" merges new notices at the top (fixture, test only)', 'TEST FIXTURE' in pg.evaluate("document.querySelector('#rl251 .rc251').innerText"))
    c.unroute(re.compile(r'https://www\.saferproducts\.gov/RestWebServices/Recall.*')); c.route(re.compile(r'https://www\.saferproducts\.gov/.*'), lambda rt: rt.abort())
    go(pg, '#/hb-about', '.hbab25', 300); go(pg, '#/recalls/c', '#rl251 .rc251', 800); pg.click('#lv251'); pg.wait_for_function("()=>document.getElementById('lv251').innerText.includes('didn')", timeout=20000); ok('[recalls] CPSC unavailable: friendly retry, no crash', True)
    pg.evaluate("sessionStorage.removeItem('lumi.scanned')")
