    ok('data: a local food has a barcode on a recall notice', bool(probe), probe)
    if probe:
        go(pg, '#/product/' + probe[0], '#rcal251', 4000); t = txt(pg)
        ok('[food product] barcode on a recall: warning with official notice link, as-of date', pg.evaluate("!!document.querySelector('#rcal251')") and 'this barcode is on a recall notice' in t and pg.evaluate("!!document.querySelector('#rcal251 a[href^=\"https://\"]')") and RJ['asof'] in t, t[:300])
        ok('[food product] warning sits near the top, right after the product header card', pg.evaluate("[...document.getElementById('app').children].indexOf(document.querySelector('#rcal251'))") in (1, 2, 3), pg.evaluate("[...document.getElementById('app').children].map(e=>e.className+'|'+e.id).slice(0,6)"))
    nf = pg.evaluate("""async()=>{ const U=await HB25UI.recUPC(); const d=engine.docs.find(d=>d.code&&/^\\d{12,13}$/.test(d.code)&&!U.m.has(d.code.replace(/^0+/,''))&&d.brand&&/^[A-Za-z ]+$/.test(d.brand)); return [d.code,d.name]; }""")
    pg.evaluate("sessionStorage.removeItem('lumi.scanned')")
    go(pg, '#/product/' + nf[0], '#app .card', 3500); ok('[food product] no recall match: no warning card', pg.evaluate("!document.querySelector('#rcal251')"), nf)
