    ok('[HB product] no recall: says where to check and that absence proves nothing (or shows a recall)', ('No recall found for this product' in t and "doesn't mean there isn't one" in t) or 'Recall' in t, t[-600:])
    pm2 = pg.evaluate("""async()=>{ const R=await HB25UI.recAll(); const a=R.items.find(x=>x[1]==='c'&&x[5]&&x[4].length>20); const nm=a[4].split(';')[0]; const m=await HB25UI.recallsFor({code:'',name:nm,brand:a[5]}); return {n:m.possible.length, strong:m.strong.length, nm, brand:a[5]}; }""")
    ok('[matching] a recall\'s own brand + product words give a possible match, never a strong one without a barcode', pm2['n'] >= 1 and pm2['strong'] == 0, pm2)
    ok('[matching] brand alone does not match', pg.evaluate("""async()=>{ const m=await HB25UI.recallsFor({code:'',name:'Zzyzx widget',brand:'Mezzetta'}); return m.possible.length===0 && m.strong.length===0; }"""))
    go(pg, '#/privacy', '.pg231', 300); ok('[privacy] CPSC recalls API row, button-only', 'CPSC Recalls API' in txt(pg) and 'Check CPSC for newer recalls' in txt(pg))
