            pages = [('#/hb/laundry', '#hbl25 .row'), (hd(s1), '.hbpg25'), (hd(f1), '.hbpg25'), ('#/recalls', '#rl251 .rc251'), ('#/recalls/f', '#rl251 .rc251')] + ([('#/product/' + probe[0], '#rcal251')] if probe else [])
